(x, y, t) => {
  const cx = 240, cy = 120;
  const n1 = Math.sin(x*0.018+t*0.4)*Math.cos(y*0.022-t*0.3);
  const n2 = Math.sin(x*0.031-t*0.55)*Math.sin(y*0.027+t*0.45);
  const n3 = Math.cos((x+y)*0.015+t*0.2)*Math.sin((x-y)*0.02-t*0.35);
  const flow = (n1+n2+n3)/3;
  const wells = [
    [160+Math.sin(t*0.5)*100, 80+Math.cos(t*0.4)*50, 40, 0.8],
    [320+Math.cos(t*0.45)*100, 160+Math.sin(t*0.6)*50, 35, 0.9],
    [240+Math.sin(t*0.3+2)*130, 120+Math.cos(t*0.5+1)*80, 50, 0.7],
    [120+Math.cos(t*0.7+1)*80, 180+Math.sin(t*0.55+3)*60, 30, 1.0],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.8+2)*70, 45, 0.75],
    [240+Math.cos(t*0.35+5)*110, 200+Math.sin(t*0.5)*70, 38, 0.85],
    [80+Math.sin(t*0.6+3)*70, 40+Math.cos(t*0.45+1)*50, 25, 1.1],
    [400+Math.cos(t*0.55+2)*60, 200+Math.sin(t*0.65+4)*80, 32, 0.95]
  ];
  let gx = 0, gy = 0, potential = 0;
  for (const [wX, wY, mass, str] of wells) {
    const dx = wX-x, dy = wY-y;
    const dist = Math.sqrt(dx*dx+dy*dy)+1;
    const force = mass*str/(dist*0.5);
    gx += dx/dist*force*0.3;
    gy += dy/dist*force*0.3;
    potential += mass/(dist*0.3+5);
  }
  const sx = x+gx+flow*20, sy = y+gy+flow*20;
  let aS = 0, iS = 0;
  for (const [wX, wY, mass, str] of wells) {
    const d = Math.sqrt((sx-wX)**2+(sy-wY)**2);
    const f = 0.06+mass*0.001, sp = 1.5+str;
    aS += Math.sin(d*f-t*sp)*str;
    iS += Math.sin(d*f*0.7+t*sp*0.5+1.5)*str;
  }
  aS /= 8; iS /= 8;
  const kinetic = Math.sqrt(gx*gx+gy*gy)*0.15;
  const totalE = potential*0.3+kinetic;
  const eRatio = kinetic/(totalE+0.01);
  const bg = (Math.sin(sx*0.035+sy*0.02+t*0.9)+Math.sin(sx*0.025-sy*0.035+t*1.3))/2+Math.sin((sx+sy)*0.1+t*2.8)*0.3+Math.sin((sx-sy)*0.08-t*2.2)*0.3;
  const dist = Math.sqrt((sx-cx)**2+(sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const spiral = (Math.sin(dist*0.045-ang*4-t*1.8)+Math.sin(dist*0.035+ang*5-t*1.4))*0.4;
  const cell = Math.sin(sx*0.12+t*0.3)*Math.sin(sy*0.12-t*0.25)+Math.sin((sx*0.8+sy*0.6)*0.08+t*0.7)*0.5;
  const reaction = Math.tanh((aS-iS*0.6+bg*0.35+spiral+cell*0.4)*3.0);
  const eBoost = Math.tanh(totalE*0.8-2.0)*0.3;
  const blend = reaction+eBoost;
  const v = blend*0.5+0.5;
  const pal = [[2,2,12],[10,5,40],[20,60,180],[0,220,255],[0,255,180],[255,50,200],[255,100,255],[255,220,255],[2,2,12]];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const glow = Math.max(0, Math.abs(reaction)-0.5)*2.0;
  const edge = Math.abs(reaction)>0.75?1.4:1.0;
  const eGlow = eRatio*0.3;
  return [
    Math.min(255, (pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*(edge+glow*0.5+eGlow))|0,
    Math.min(255, (pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*(edge+glow*0.8+eGlow))|0,
    Math.min(255, (pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*(edge+glow*0.4+eGlow))|0
  ];
}
